<?php $editable=!$campaign||in_array($campaign['status'],['draft','approved'],true);$field=static fn(string$key,string$default=''):string=>isset($values[$key])&&is_scalar($values[$key])?(string)$values[$key]:$default;$path='/write/newsletter'.($campaign?'/'.$campaign['id']:'/new');$future=(new DateTimeImmutable('+1 hour',new DateTimeZone((string)app_config('timezone','Africa/Nairobi'))))->format('Y-m-d\TH:i'); ?>
<main class="write-main nl-main">
  <div class="writer-head"><div><span class="writer-kicker">Draft · Review · Schedule</span><h1><?=e($campaign?$campaign['title']:'Prepare a newsletter')?></h1><p class="nl-lead">Save your words, review the exact email and approve a version before choosing its audience and release time.</p></div><a class="wbtn" href="<?=url('/write/newsletter')?>">All editions</a></div>
  <nav class="nl-nav" aria-label="Edition sections"><a href="#compose">Compose</a><?php if($campaign):?><a href="#review">Saved preview & approval</a><a href="#release">Release controls</a><a href="<?=url($path.'/report')?>">Delivery report</a><?php endif;?></nav>
