  <form id="compose" data-editor-form data-post-id="" method="post" action="<?=url($path)?>" class="nl-section"><?=csrf_field()?><input type="hidden" name="draft_version" value="<?=intval($campaign['draft_version']??0)?>"><input type="hidden" name="content_html" value="<?=e($field('body_html'))?>">
    <div class="nl-card"><div class="field"><label for="nl-title">Edition title · private label</label><input id="nl-title" name="title" maxlength="180" required value="<?=e($field('title'))?>"></div><div class="field"><label for="nl-subject">Email subject</label><input id="nl-subject" name="subject" maxlength="200" value="<?=e($field('subject'))?>"></div><div class="field"><label for="nl-preheader">Inbox preview text</label><textarea id="nl-preheader" name="preheader" maxlength="240" rows="2"><?=e($field('preheader'))?></textarea></div><div class="field"><label for="nl-source">Linked public article · optional</label><select id="nl-source" name="source_post_id"><option value="">Standalone edition</option><?php foreach($posts as$post):?><option value="<?=intval($post['id'])?>" <?=$field('source_post_id')===(string)$post['id']?'selected':''?>><?=e($post['title'])?></option><?php endforeach;?></select><small>A linked article must be public before saving and remain public at delivery time. Its topic and public journey scope are frozen at approval; readers who chose those subjects can match this edition.</small></div>
      <h2>Email body</h2><div class="toolbar" aria-label="Newsletter formatting"><button type="button" data-cmd="bold"><strong>B</strong></button><button type="button" data-cmd="italic"><em>I</em></button><button type="button" data-cmd="formatBlock" data-value="h2">Heading</button><button type="button" data-cmd="formatBlock" data-value="p">Paragraph</button><button type="button" data-cmd="insertUnorderedList">List</button><button type="button" data-cmd="formatBlock" data-value="blockquote">Quote</button><button type="button" data-cmd="createLink" onclick="this.dataset.value=prompt('Public HTTPS link')||''">Link</button><button type="button" data-cmd="insertImage" onclick="this.dataset.value=prompt('Public HTTPS image URL')||''">Image</button><button type="button" data-cmd="removeFormat">Clear formatting</button></div>
      <div class="editor-body nl-body" contenteditable="true" role="textbox" aria-label="Newsletter email body" aria-multiline="true" data-editor-body spellcheck="true"><?=sanitize_html($field('body_html','<p></p>'))?></div>
