  <?php else:?><section id="compose" class="nl-card"><span class="nl-status <?=e($campaign['status'])?>"><?=e(newsletter_status_label($campaign['status']))?></span><p>This edition’s approved content and recipient snapshot are locked. A new copy starts as a private draft without recipients or approval.</p><form method="post" action="<?=url($path.'/duplicate')?>"><?=csrf_field()?><button class="wbtn" type="submit">Copy into a new draft</button></form></section><?php endif;?>
  <?php if($campaign):?>
  <section id="review" class="nl-section"><h2>Review the saved email</h2><p>Saved draft version <?=intval($campaign['draft_version'])?><?php if($revision):?> · approved <?=e(newsletter_local_time($revision['approved_at']))?><?php endif;?>.</p>
    <?php if($reviewError):?><div class="notice error"><?=e($reviewError)?></div><div class="nl-card"><?=sanitize_html($campaign['body_html'])?></div><?php endif;?>
    <?php if($snapshot):?><div class="nl-card"><dl class="nl-meta"><dt>From</dt><dd><?=e($snapshot['sender']['name'].' <'.$snapshot['sender']['from'].'>')?></dd><dt>Reply to</dt><dd><?=e($snapshot['sender']['reply_to']?:$snapshot['sender']['from'])?></dd><?php if(isset($snapshot['reader_audience'])):?><dt>Reader scope</dt><dd><?=e($snapshot['reader_audience']['labels']?implode(', ',$snapshot['reader_audience']['labels']).' or all-writing subscribers':'All-writing subscribers')?></dd><?php endif;?><dt>Subject</dt><dd><?=e($snapshot['subject'])?></dd><dt>Preview text</dt><dd><?=e($snapshot['preheader']?:'—')?></dd></dl><iframe title="Saved newsletter email preview" class="nl-preview" sandbox="" referrerpolicy="no-referrer" srcdoc="<?=e(newsletter_html($snapshot))?>"></iframe><a href="<?=url($path.'/preview')?>" target="_blank" rel="noopener noreferrer">Open saved preview ↗</a></div><?php endif;?>
    <?php if($editable&&!$revision&&$snapshot):?><form class="nl-card nl-section" method="post" action="<?=url($path.'/approve')?>"><?=csrf_field()?><input type="hidden" name="draft_version" value="<?=intval($campaign['draft_version'])?>"><input type="hidden" name="review_hash" value="<?=e(hash('sha256',newsletter_json($snapshot)))?>"><h3>Approve this exact saved version</h3><label class="nl-check"><input type="checkbox" name="approve_content" value="1" required><span>I reviewed the saved subject, body, sender and unsubscribe footer above.</span></label><label class="nl-check"><input type="checkbox" name="permission_ack" value="1" required><span>I have permission to publish the included text, images and personal information.</span></label><button class="wbtn primary" type="submit">Approve saved edition</button></form><?php endif;?>
  </section>
  <section id="release" class="nl-section"><h2>Release controls</h2><div class="nl-card"><span class="nl-status <?=e($campaign['status'])?>"><?=e(newsletter_status_label($campaign['status']))?></span><p><?=email_transport_ready()?'Mail transport is configured.':'Mail transport is disabled; queued messages will stay offline.'?> <?=app_config('worker_enabled',false)?'Background work is enabled.':'Background work is disabled.'?></p>
    <?php if($campaign['status']==='approved'&&$revision):?><form method="post" action="<?=url($path.'/schedule')?>"><?=csrf_field()?><input type="hidden" name="revision_id" value="<?=intval($revision['id'])?>"><input type="hidden" name="state_version" value="<?=intval($campaign['state_version'])?>"><div class="field"><label for="nl-schedule">Release time · <?=e((string)app_config('timezone','Africa/Nairobi'))?></label><input id="nl-schedule" type="datetime-local" name="scheduled_at" value="<?=e($future)?>" required></div><label class="nl-check"><input type="checkbox" name="audience_ack" value="1" required><span>Send this approved edition to a snapshot of the currently eligible, confirmed subscribers. New confirmations after scheduling will not join this edition.</span></label><p class="nl-help">Unsubscribed, suppressed and unconfirmed addresses are excluded. Topic and journey choices are also respected; standalone editions go to readers who selected all writing. Eligibility is checked again immediately before each send.</p><button class="wbtn primary" type="submit">Schedule approved edition</button></form><?php endif;?>
    <?php if($campaign['scheduled_at']):?><p>Scheduled <?=e(newsletter_local_time($campaign['scheduled_at']))?> · <?=intval($campaign['audience_size'])?> recipients in the original snapshot.</p><a class="wbtn" href="<?=url($path.'/report')?>">View delivery report</a><?php endif;?>
    <?php if(in_array($campaign['status'],['scheduled','sending'],true)):?><form method="post" action="<?=url($path.'/pause')?>" class="nl-section"><?=csrf_field()?><input type="hidden" name="state_version" value="<?=intval($campaign['state_version'])?>"><button class="wbtn" type="submit">Pause remaining deliveries</button></form><?php endif;?>
    <?php if($campaign['status']==='paused'):?><form method="post" action="<?=url($path.'/resume')?>" class="nl-section"><?=csrf_field()?><input type="hidden" name="state_version" value="<?=intval($campaign['state_version'])?>"><div class="field"><label for="nl-resume">Resume at · <?=e((string)app_config('timezone','Africa/Nairobi'))?></label><input id="nl-resume" type="datetime-local" name="scheduled_at" value="<?=e($future)?>" required></div><button class="wbtn primary" type="submit">Resume the same edition</button></form><?php endif;?>
    <?php if(!in_array($campaign['status'],['completed','cancelled'],true)):?><details class="nl-section"><summary>Cancel this edition</summary><form method="post" action="<?=url($path.'/cancel')?>"><?=csrf_field()?><input type="hidden" name="state_version" value="<?=intval($campaign['state_version'])?>"><label class="nl-check"><input type="checkbox" name="confirm_cancel" value="1" required><span>Cancel the remaining deliveries. Messages already accepted by the provider cannot be recalled; uncertain outcomes stay recorded.</span></label><button class="wbtn" type="submit">Cancel remaining deliveries</button></form></details><?php endif;?>
  </div></section>
  <?php endif;?>
